package com.therighthon.rnr.common.block;
import com.therighthon.rnr.common.RNRBlockEntities; import com.therighthon.rnr.common.blockentity.RNRTickCounterBlockEntity; import com.therighthon.rnr.common.blockentity.RNRTickCounterBlockEntity; import net.minecraft.core.BlockPos; import net.minecraft.core.Direction; import net.minecraft.server.level.ServerLevel; import net.minecraft.util.RandomSource; import net.minecraft.world.entity.Entity; import net.minecraft.world.entity.LivingEntity; import net.minecraft.world.level.BlockGetter; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.Blocks; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.phys.shapes.CollisionContext; import net.minecraft.world.phys.shapes.VoxelShape;
public class WetConcretePathBlock extends PathHeightDeviceBlock implements net.minecraft.world.level.block.EntityBlock { public static final int TICKS_TO_DRY=24000; private static final float defaultSpeedFactor=.7f; public WetConcretePathBlock(Properties p){super(p.speedFactor(defaultSpeedFactor).randomTicks());} public VoxelShape getCollisionShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return BaseCourseHeightBlock.SHAPE;} public static float getDefaultSpeedFactor(){return defaultSpeedFactor;} public void onPlace(BlockState s,Level l,BlockPos p,BlockState old,boolean moving){RNRTickCounterBlockEntity.reset(l,p);} public void entityInside(BlockState s,Level l,BlockPos p,Entity e){if(!l.isClientSide&&e instanceof LivingEntity)l.setBlock(p,RNRBlocks.TRODDEN_WET_CONCRETE_ROAD.get().withPropertiesOf(s),3);} public void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){if(l.getBlockEntity(p) instanceof RNRTickCounterBlockEntity c&&c.getTicksSinceUpdate()>TICKS_TO_DRY)l.setBlockAndUpdate(p,getOutputState(s));} public BlockState getOutputState(BlockState in){if(in.is(RNRBlocks.WET_CONCRETE_ROAD.get()))return RNRBlocks.CONCRETE_ROAD.get().defaultBlockState();if(in.is(RNRBlocks.TRODDEN_WET_CONCRETE_ROAD.get()))return RNRBlocks.TRODDEN_CONCRETE_ROAD.get().defaultBlockState();if(in.is(RNRBlocks.WET_CONCRETE_ROAD_CONTROL_JOINT.get()))return RNRBlocks.CONCRETE_ROAD_CONTROL_JOINT.get().withPropertiesOf(in);if(in.is(RNRBlocks.WET_CONCRETE_ROAD_PANEL.get()))return RNRBlocks.CONCRETE_ROAD_PANEL.get().withPropertiesOf(in);if(in.is(RNRBlocks.WET_CONCRETE_ROAD_SETT.get()))return RNRBlocks.CONCRETE_ROAD_SETT.get().withPropertiesOf(in);if(in.is(RNRBlocks.WET_CONCRETE_ROAD_FLAGSTONES.get()))return RNRBlocks.CONCRETE_ROAD_FLAGSTONES.get().withPropertiesOf(in);return Blocks.AIR.defaultBlockState();} public boolean isRandomlyTicking(BlockState s){return true;} public net.minecraft.world.level.block.entity.BlockEntity newBlockEntity(BlockPos p,BlockState s){return new RNRTickCounterBlockEntity(p,s);} }
